approaches.measure-required:
"""Every KPI item is a countable measure (approach measure-required)."""
import re

MEASURED = re.compile('scored|rated|checklist|\\d', re.I)


def apply(case):
    pack = case["pack"]
    for index, card in enumerate(pack.get("activation_cards") or []):
        for item in re.split(r",| and ", str(card.get("kpi") or "")):
            item = item.strip()
            if re.search(r"\bquality\b", item, re.I) and not MEASURED.search(item):
                raise ValueError(
                    f"tactical_roadmap_kpi_unmeasured: activation_cards[{index}] ({card.get('name')}) "
                    f"KPI {item!r} names no measure -- state how it is scored (e.g. 'post quality "
                    "scored 1-5 against the approved-copy checklist') or drop it."
                )
    return {"refusal": None, "rendered": "", "pack": pack}

